export type Handler = (request: Request, response: Response) => void;

export interface Request {
  path: string;
}

export interface Response {
  send(body: unknown): void;
}

export interface App {
  get(path: string, handler: Handler): this;
  post(path: string, handler: Handler): this;
  /** Serves `child`'s routes under `prefix`. */
  route(prefix: string, child: App): this;
}

/** One app the package builds itself. */
export declare const shared: App;

declare function make(options?: object): App;
export default make;
